                      "value": "[parameters('EnableWindowsNTPClient')]"
                    },
                    "TurnOnConveniencePINSignin": {
                      "value": "[parameters('TurnOnConveniencePINSignin')]"
                    }
                  },
                  "template": {
                    "$schema": "https://schema.management.azure.com/schemas/2015-01-01/deploymentTemplate.json#",
