                              {
                                "name": "Audit: Shut down system immediately if unable to log security audits;ExpectedValue",
                                "value": "[parameters('AuditShutDownSystemImmediatelyIfUnableToLogSecurityAudits')]"
                              }
                            ]
                          }
                        }
                      },
                      {
                        "apiVersion": "2017-03-30",
