                              }
                            }
                          ],
                          "logs": [
                            {
                              "category": "Audit",
                              "enabled": "[parameters('logsEnabled')]"
                            },
                            {
                              "category": "Requests",
                              "enabled": "[parameters('logsEnabled')]"
                            }
                          ]
                        }
                      }
                    ],
                    "outputs": {}
                  },
                  "parameters": {
